import java.util.*;

class Solution {
    public int countCircles(int[][] friends) {
        int n = friends.length, circles = 0;
        boolean[] seen = new boolean[n];
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            circles++; // new circle starts here
            seen[i] = true;
            stack.push(i);
            while (!stack.isEmpty()) {
                int s = stack.pop();
                for (int j = 0; j < n; j++)
                    if (friends[s][j] == 1 && !seen[j]) { seen[j] = true; stack.push(j); }
            }
        }
        return circles;
    }
}

