class Solution:
    def countCircles(self, friends: List[List[int]]) -> int:
        n = len(friends); seen = [False] * n; cnt = 0
        for s in range(n):
            if seen[s]: continue
            cnt += 1; seen[s] = True; st = [s]
            while st:
                v = st.pop()
                for u in range(n):
                    if friends[v][u] and not seen[u]:
                        seen[u] = True; st.append(u)
        return cnt

