function countCircles(friends) {
  const n = friends.length, p = [...Array(n).keys()];
  const f = x => { while (p[x] !== x) { p[x] = p[p[x]]; x = p[x]; } return x; };
  let cnt = n;
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) if (friends[i][j]) { const a = f(i), b = f(j); if (a !== b) { p[a] = b; cnt--; } }
  return cnt;
}
